USE master
GO
--drop database if it exists
IF DB_ID('BooksPlus') IS NOT NULL
BEGIN
	ALTER DATABASE BooksPlus SET SINGLE_USER WITH ROLLBACK IMMEDIATE
	DROP DATABASE BooksPlus
END
GO

CREATE DATABASE BooksPlus
GO
PRINT 'BooksPlus database created'

USE BooksPlus
GO
PRINT ''
PRINT '---------------'
PRINT 'Creating tables'
PRINT '---------------'
PRINT ''

CREATE TABLE dbo.Author
(
	AuthorId int IDENTITY(1,1) NOT NULL PRIMARY KEY,
	FirstName nvarchar(100) NOT NULL,
	LastName nvarchar(255) NOT NULL,
	Phone nvarchar(50) NULL,
	Email nvarchar(255) NOT NULL,
	StreetAddress nvarchar(100) NULL,
	City nvarchar(50) NULL,
	StateId int NULL,
	PostalCode nvarchar(20) NULL,
	ModifiedDate datetime2(7) NOT NULL DEFAULT SYSDATETIME()
)
GO
PRINT 'Author table created.'

CREATE TABLE dbo.AuthorCategory
(
	AuthorId int NOT NULL,
	CategoryId int NOT NULL,
	PRIMARY KEY
	(
		AuthorID ASC,
		CategoryId ASC
	)
)
GO
PRINT 'AuthorCategory table created.'

CREATE TABLE dbo.Book
(
	BookId int IDENTITY(1,1) NOT NULL PRIMARY KEY,
	BookTypeId int NOT NULL,
	CategoryId int NOT NULL,
	PublisherId int NULL,
	Title nvarchar(255) NOT NULL,
	PublishDate date NOT NULL,
	Summary nvarchar(max) NULL,
	Price decimal(5, 2) NULL,
	ISBN nchar(13) NULL,
	UnitsInStock int NULL,
	ReorderLevel int NULL,
	UnitsOnOrder int NULL,
	ModifiedDate datetime2(7) NOT NULL DEFAULT SYSDATETIME()
)
GO
PRINT 'Book table created.'

CREATE TABLE dbo.BookAuthor
(
	BookId int NOT NULL,
	AuthorId int NOT NULL,
	RoyaltyPercentage decimal(3, 2) NOT NULL,
	ModifiedDate datetime2(7) NOT NULL DEFAULT SYSDATETIME(),
	PRIMARY KEY
	(
		BookId ASC,
		AuthorId ASC
	)
)
GO
PRINT 'BookAuthor table created.'

CREATE TABLE dbo.BookTag
(
	BookId int NOT NULL,
	Tag nvarchar(100) NOT NULL,
	PRIMARY KEY
	(
		BookId ASC,
		Tag ASC
	)
)
GO
PRINT 'BookTag table created.'

CREATE TABLE dbo.BookType
(
	BookTypeId INT IDENTITY(1,1) NOT NULL PRIMARY KEY,
	TypeName nvarchar(100) NOT NULL
)
GO
PRINT 'BookType table created.'

CREATE TABLE dbo.Carrier
(
	CarrierId int IDENTITY(1,1) NOT NULL PRIMARY KEY,
	CarrierName nvarchar(100) NOT NULL,
	ModifiedDate datetime2(7) NOT NULL
)
GO
PRINT 'Carrier table created.'

CREATE TABLE dbo.Category
(
	CategoryId int IDENTITY(1,1) NOT NULL PRIMARY KEY,
	CategoryName nvarchar(50) NOT NULL,
	Description nvarchar(max) NULL,
	ModifiedDate datetime2(7) NOT NULL DEFAULT SYSDATETIME()
)
GO
PRINT 'Category table cSEreated.'

CREATE TABLE dbo.Country
(
	CountryId int IDENTITY(1,1) NOT NULL PRIMARY KEY,
	CountryCode nvarchar(5) NOT NULL,
	CountryName nvarchar(255) NOT NULL,
	Currency nvarchar(100) NOT NULL,
	CurrencyCode nvarchar(5) NOT NULL,
	CurrencySymbol nvarchar(5) NOT NULL,
	ModifiedDate datetime2(7) NOT NULL DEFAULT SYSDATETIME()
)
GO
PRINT 'Country table created.'

CREATE TABLE dbo.Customer
(
	CustomerId int IDENTITY(1,1) NOT NULL PRIMARY KEY,
	FirstName nvarchar(100) NOT NULL,
	MiddleInitial NCHAR(1) NULL,
	LastName nvarchar(100) NOT NULL,
	Email nvarchar(255) NULL,
	Phone varchar(20) NULL,
	UserId int NULL,
	StreetAddress nvarchar(100) NULL,
	City nvarchar(50) NULL,
	StateId int NULL,
	PostalCode nvarchar(20) NULL,
	ModifiedDate datetime2(7) NOT NULL DEFAULT SYSDATETIME()
)
GO
PRINT 'Customer table created.'

CREATE TABLE dbo.Department
(
	DepartmentId int IDENTITY(1,1) NOT NULL PRIMARY KEY,
	DepartmentName nvarchar(100) NOT NULL
)
GO
PRINT 'Department table created.'

CREATE TABLE dbo.Employee
(
	EmployeeId int IDENTITY(1,1) NOT NULL PRIMARY KEY,
	StoreId int NOT NULL,
	ManagerId int NULL,
	DepartmentId int NOT NULL,
	FirstName nvarchar(100) NOT NULL,
	LastName nvarchar(255) NOT NULL,
	JobTitle nvarchar(100) NOT NULL,
	Salary decimal(10, 2) NULL,
	ModifiedDate datetime2(7) NOT NULL DEFAULT SYSDATETIME()
)
GO
PRINT 'Employee table created.'

CREATE TABLE dbo.[Order]
(
	OrderId int IDENTITY(1001,1) NOT NULL PRIMARY KEY,
	CustomerId int NOT NULL,
	StoreId int NOT NULL,
	EmployeeId int NULL,
	OrderStatusId int NOT NULL,
	CarrierId int NULL,
	OrderDate datetime2(7) NOT NULL,
	ShipDate datetime2(7) NULL,
	SubTotal decimal(10, 2) NULL,
	Discount decimal(10, 2) NULL,
	Tax decimal(10, 2) NULL,
	Freight decimal(10, 2) NULL,
	OrderTotal decimal(10, 2) NULL,
	Notes nvarchar(4000) NULL,
	ModifiedDate datetime2(7) NOT NULL DEFAULT SYSDATETIME()
)
GO
PRINT 'Order table created.'

CREATE TABLE dbo.OrderLineItem
(
	OrderLineItemId int IDENTITY(1,1) NOT NULL PRIMARY KEY,
	OrderId int NOT NULL,
	BookId int NOT NULL,
	UnitPrice decimal(10,2) NOT NULL,
	Quantity int NOT NULL,
	UnitPriceDiscount decimal(10, 2) NOT NULL,
	LineTotal decimal(10, 2) NOT NULL,
	TrackingNumber nvarchar(25) NULL,
	ModifiedDate datetime2(7) NOT NULL DEFAULT SYSDATETIME()
)
GO
PRINT 'OrderLineItem table created.'

CREATE TABLE dbo.OrderStatus
(
	OrderStatusId INT IDENTITY(1,1) NOT NULL PRIMARY KEY,
	StatusName nvarchar(20) NOT NULL
)
GO
PRINT 'OrderStatus table created.'

CREATE TABLE dbo.Publisher
(
	PublisherId int IDENTITY(1,1) NOT NULL PRIMARY KEY,
	PublisherName nvarchar(255) NOT NULL,
	Phone NVARCHAR(20) NULL,
	Email NVARCHAR(200) NULL,
	StreetAddress nvarchar(100) NULL,
	City nvarchar(50) NULL,
	StateId int NULL,
	PostalCode nvarchar(20) NULL,
	ModifiedDate datetime2(7) NOT NULL DEFAULT SYSDATETIME()
)
GO
PRINT 'Publisher table created.'

CREATE TABLE dbo.Region
(
	RegionId INT IDENTITY(1,1) NOT NULL PRIMARY KEY,
	RegionName nvarchar(100) NOT NULL,
	ModifiedDate datetime NOT NULL DEFAULT SYSDATETIME()
)
GO
PRINT 'Region table created.'

CREATE TABLE dbo.[Role]
(
	RoleName NVARCHAR(200) NOT NULL PRIMARY KEY
)
GO
PRINT 'Role table created.'

CREATE TABLE dbo.[State]
(
	StateId int IDENTITY(1,1) NOT NULL PRIMARY KEY,
	StateCode nvarchar(100) NOT NULL,
	StateName nvarchar(100) NOT NULL,
	CountryId int NOT NULL,
	ModifiedDate datetime2(7) NOT NULL DEFAULT SYSDATETIME()
)
GO
PRINT 'State table created.'

CREATE TABLE dbo.Store
(
	StoreId INT IDENTITY(1,1) NOT NULL PRIMARY KEY,
	RegionId int NOT NULL,
	StoreName nvarchar(100) NOT NULL,
	Url nvarchar(255) NOT NULL,
	StreetAddress nvarchar(100) NULL,
	City nvarchar(50) NULL,
	StateId int NULL,
	PostalCode nvarchar(20) NULL,
	ModifiedDate datetime NOT NULL DEFAULT SYSDATETIME()
)
GO
PRINT 'Store table created.'

CREATE TABLE dbo.[User] 
(
	UserId INT IDENTITY(1,1) NOT NULL PRIMARY KEY,
	UserName NVARCHAR(200) NOT NULL,
	HashedPassword NVARCHAR(2000) NOT NULL,
	Salt NVARCHAR(2000) NOT NULL
)
GO
PRINT 'User table created.'

CREATE	TABLE UserRole 
(
	UserId INT NOT NULL,
	RoleName NVARCHAR(200) NOT NULL,
	PRIMARY KEY (
		UserId,
		RoleName
	)
)
GO
PRINT 'UserRole table created.'


