PRINT ''
PRINT 'Begin updating Discounts'

UPDATE dbo.OrderLineItem
SET UnitPriceDiscount = .0
WHERE UnitPriceDiscount IN (.4, .5)

UPDATE dbo.OrderLineItem
SET UnitPriceDiscount = .3
WHERE UnitPriceDiscount = .1

UPDATE dbo.OrderLineItem
SET UnitPriceDiscount = .2
WHERE UnitPriceDiscount = .25

UPDATE dbo.OrderLineItem
SET UnitPriceDiscount = .1
WHERE UnitPriceDiscount = .33


UPDATE dbo.OrderLineItem
SET UnitPriceDiscount = .3
WHERE Quantity = 10

UPDATE dbo.OrderLineItem
SET LineTotal = CAST((UnitPrice * (1 - UnitPriceDiscount)) * Quantity AS NUMERIC(10,2))

PRINT ''
PRINT 'Finished updating Discounts'
